style.css:
@-moz-document domain("mezzoscholen.magister.net") {
/* BACKGROUND */
html, body, #app, app-root {
    background-color: #08060e !important;
    color: #f4edff !important;
}

/* Main background gradient */
body {
    background-image:
      radial-gradient(ellipse at 15% 20%,
        rgba(130, 25, 210, .35), transparent 45%),
      radial-gradient(ellipse at 85% 75%,
        rgba(220, 20, 75, .25), transparent 45%) !important;
    background-attachment: fixed !important;
}

/* Main containers */
main, [role="main"],
[class*="main-content"],
[class*="page-content"] {
    background: transparent !important;
}

/* Glass panels */
[class*="card"],
[class*="panel"],
[class*="widget"] {
    background: rgba(17, 12, 29, .72) !important;
    backdrop-filter: blur(20px) !important;
    border: 1px solid rgba(160, 75, 255, .22) !important;
    border-radius: 16px !important;
    box-shadow: 0 8px 30px rgba(0,0,0,.25) !important;
}

/* Navigation tabs */
[role="tab"],
[class*="tab"] {
    background: rgba(255,255,255,.035) !important;
    border: 1px solid rgba(180,120,255,.16) !important;
    border-radius: 14px !important;
    color: #d8c9e9 !important;
    box-shadow: none !important;
    transition: all .25s ease !important;
}

[role="tab"]:hover,
[class*="tab"]:hover {
    background: rgba(155,70,255,.14) !important;
    border-color: #a855ff !important;
    box-shadow: 0 0 18px rgba(168,85,255,.25) !important;
    transform: translateY(-2px);
}

/* Active tab */
[role="tab"][aria-selected="true"] {
    background: linear-gradient(
        110deg,
        rgba(130,40,220,.35),
        rgba(220,35,90,.22)
    ) !important;
    border-color: rgba(190,100,255,.65) !important;
    color: white !important;
    box-shadow: 0 0 18px rgba(155,60,255,.25) !important;
}

/* Sidebar and header */
header, nav, aside,
[class*="sidebar"],
[class*="navigation"] {
    background: rgba(9,7,17,.72) !important;
    backdrop-filter: blur(24px) !important;
    border-color: rgba(160,75,255,.2) !important;
}

/* Buttons */
button, [role="button"] {
    background: linear-gradient(
        110deg, #7928ca, #c02665
    ) !important;
    color: white !important;
    border: 1px solid rgba(200,130,255,.4) !important;
    border-radius: 10px !important;
    box-shadow: 0 0 12px rgba(150,50,255,.15) !important;
}

/* Text */
body, p, span, label, td, th {
    color: #eee6fa;
}

/* Inputs */
input, textarea, select {
    background: rgba(10,7,19,.8) !important;
    color: white !important;
    border: 1px solid rgba(168,85,255,.5) !important;
    border-radius: 9px !important;
}

/* Scrollbar */
* {
    scrollbar-color: #963dff #100b19;
}
}
